const MS_PER_HOUR = 60 * 60 * 1000;

/**
 * How long an archived row stays restorable: the plan's `retentionDays`, in
 * milliseconds. The retention sweep purges on the same window.
 */
export function restoreWindowMs(retentionDays: number): number {
  return retentionDays * 24 * MS_PER_HOUR;
}

/** True once the restore window has fully elapsed since `archivedAt`. */
export function isExpired(
  archivedAt: IsoTimestamp,
  retentionDays: number,
  now: Date = new Date(),
): boolean {
  return now.getTime() - Date.parse(archivedAt) >= restoreWindowMs(retentionDays);
}

export type RestoreRefusalReason =
  | "not_archived"
