/**
 * Next per-project issue number. Archived issues keep their number, and a
 * purged issue must not hand its number back, so the project's high-water mark
 * is taken alongside the max over the rows that still exist.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const project = db
    .select({ value: projects.lastIssueNumber })
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .get();
  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  return Math.max(project?.value ?? 0, row?.value ?? 0) + 1;
}

