/**
 * Archived issues whose restore window closed at or before `cutoff`, oldest
 * first. The retention sweep drains these in batches until none are left.
 */
export async function listExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
  limit: number,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        isNotNull(issues.archivedAt),
        lte(issues.archivedAt, cutoff),
      ),
    )
    .orderBy(asc(issues.archivedAt), asc(issues.id))
    .limit(limit)
    .all();

  return rows.map((row) => toIssue(row));
}

export interface PurgeResult {
  /** Comments removed with their issues; their search documents go too. */
  readonly commentIds: readonly CommentId[];
  /** Storage the removed attachments were counted for, in whole MB each. */
  readonly storageMb: number;
}

/**
 * Hard-deletes issues together with their label links, comments and
 * attachments, in one transaction. The caller clears the search index and the
 * storage counter from the returned result.
 */
export async function purgeIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<PurgeResult> {
  if (issueIds.length === 0) return { commentIds: [], storageMb: 0 };

  const ids = [...issueIds];
  return getDb().transaction((tx) => {
    const attachmentRows = tx
      .select({ sizeBytes: attachments.sizeBytes })
      .from(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          inArray(attachments.issueId, ids),
        ),
      )
      .all();

    const commentRows = tx
      .select({ id: comments.id })
      .from(comments)
      .where(
        and(
          orgPredicate(comments.orgId, orgId),
          inArray(comments.issueId, ids),
        ),
      )
      .all();

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          inArray(issueLabels.issueId, ids),
        ),
      )
      .run();

    tx.delete(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          inArray(attachments.issueId, ids),
        ),
      )
      .run();

    tx.delete(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), inArray(comments.issueId, ids)),
      )
      .run();

    tx.delete(issues)
      .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, ids)))
      .run();

    return {
      commentIds: commentRows.map((row) => row.id as CommentId),
      storageMb: attachmentRows.reduce(
        (total, row) => total + megabytesFor(row.sizeBytes),
        0,
      ),
    };
  });
}

