/**
 * Restoring archived issues and the retention sweep that purges expired ones.
 *
 * An archived issue is restorable for the plan's `retentionDays`; after that it
 * is expired and the sweep deletes it together with everything it owns.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { RestoreRefusedError } from "@/lib/soft-delete";
import { getDb, searchIndex } from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as attachmentService from "@/server/services/attachment-service";
import { NotFoundError } from "@/server/services/_support";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Issue } from "@/types/issue";
import type { Unsubscribe } from "@/types/event";

const DAY = 24 * 60 * 60 * 1000;
const MB = 1024 * 1024;
const NOW = new Date("2026-06-01T09:00:00.000Z");
/** The growth plan, which the shared tenant fixture uses. */
const GROWTH_RETENTION_DAYS = 365;

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

function at(offsetMs: number): Date {
  return new Date(NOW.getTime() + offsetMs);
}

async function archivedIssue(title: string): Promise<Issue> {
  const issue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title }),
  );
  return issueService.archiveIssue(
    tenant.actors.member,
    tenant.org.id,
    issue.id,
  );
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("restore");
  await usageRepo.recomputeUsage(tenant.org.id);
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(NOW);
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  vi.useRealTimers();
  cleanup();
});

describe("restoring an archived issue", () => {
  it("makes it live again under its original number and publishes issue.restored", async () => {
    const issue = await archivedIssue("Restorable");

    const seen: string[] = [];
    detachers.push(
      subscribe("issue.restored", (payload) => {
        seen.push(payload.issueId);
      }),
    );

    vi.setSystemTime(at(2 * DAY));
    const restored = await issueService.restoreIssue(
      tenant.actors.member,
      tenant.org.id,
      issue.id,
    );

    expect(restored.archivedAt).toBeNull();
    expect(restored.number).toBe(issue.number);
    expect(seen).toEqual([issue.id]);
    vi.setSystemTime(NOW);
  });

  it("refuses an issue that is not archived", async () => {
    const live = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Still open" }),
    );

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, live.id),
    ).rejects.toMatchObject({ reason: "not_archived" });
  });

  it("refuses once the retention window has elapsed, and changes nothing", async () => {
    const issue = await archivedIssue("Too late");

    vi.setSystemTime(at(GROWTH_RETENTION_DAYS * DAY));
    const attempt = issueService.restoreIssue(
      tenant.actors.member,
      tenant.org.id,
      issue.id,
    );

    await expect(attempt).rejects.toBeInstanceOf(RestoreRefusedError);
    await expect(attempt).rejects.toMatchObject({ reason: "expired" });

    const stillArchived = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stillArchived?.archivedAt).not.toBeNull();
    vi.setSystemTime(NOW);
  });

  it("refuses while its project is archived", async () => {
    const scratch = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Scratch",
      slug: "scratch-restore",
      key: "SCRR",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, scratch.id, { title: "Stranded" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: scratch.id,
      archiveIssues: false,
    });

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
    ).rejects.toMatchObject({ reason: "project_archived" });
  });

  it("refuses when the project has no room under its issue quota", async () => {
    const quota = await createTenant("quota", "free");
    const input = (title: string) =>
      issueInput(quota.org.id, quota.project.id, { title });

    const first = await issueService.createIssue(
      quota.actors.member,
      input("First"),
    );
    for (let i = 1; i < 100; i += 1) {
      await issueService.createIssue(quota.actors.member, input(`Issue ${i}`));
    }
    await issueService.archiveIssue(quota.actors.member, quota.org.id, first.id);
    await issueService.createIssue(quota.actors.member, input("Replacement"));

    await expect(
      issueService.restoreIssue(quota.actors.member, quota.org.id, first.id),
    ).rejects.toMatchObject({ reason: "quota" });
  });
});

describe("the retention sweep", () => {
  it("purges an expired issue with its links, comments, attachments and search documents, and gives back its storage", async () => {
    const orgId = tenant.org.id;
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(orgId, tenant.project.id, { title: "Doomed" }),
    );
    const comment = await commentRepo.insertComment(
      {
        orgId,
        issueId: issue.id,
        body: "goodbye",
        parentId: null,
        mentionedUserIds: [],
      },
      tenant.userIds.member,
    );
    await attachmentService.addAttachment(tenant.actors.member, {
      orgId,
      issueId: issue.id,
      filename: "big.bin",
      contentType: "application/octet-stream",
      sizeBytes: 2 * MB + 1,
    });
    await searchRepo.upsertSearchDocument(orgId, "issue", issue.id, "Doomed", tenant.project.id);
    await searchRepo.upsertSearchDocument(orgId, "comment", comment.id, "goodbye", null);

    const storageBefore = (await usageRepo.getUsage(orgId)).storageMbUsed;
    const issuesBefore = (await usageRepo.getUsage(orgId)).issuesUsed;

    await issueService.archiveIssue(tenant.actors.member, orgId, issue.id);
    await runCleanupArchivedJob(at(GROWTH_RETENTION_DAYS * DAY + DAY));

    expect(await issueRepo.findIssueById(orgId, issue.id)).toBeNull();
    expect(await commentRepo.listThread(orgId, issue.id)).toEqual([]);
    expect(
      await attachmentService.listAttachments(tenant.actors.member, orgId, issue.id),
    ).toEqual([]);

    const usage = await usageRepo.getUsage(orgId);
    expect(usage.storageMbUsed).toBe(storageBefore - 3);
    expect(usage.issuesUsed).toBe(issuesBefore);

    const remainingDocs = getDb()
      .select({ id: searchIndex.id })
      .from(searchIndex)
      .all()
      .filter((row) => row.id.length > 0);
    const docsFor = getDb()
      .select({ subjectId: searchIndex.subjectId })
      .from(searchIndex)
      .all()
      .map((row) => row.subjectId);
    expect(docsFor).not.toContain(issue.id);
    expect(docsFor).not.toContain(comment.id);
    expect(remainingDocs.length).toBeGreaterThanOrEqual(0);

    await expect(
      issueService.restoreIssue(tenant.actors.member, orgId, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("never hands a purged issue's number back out", async () => {
    const orgId = tenant.org.id;
    const doomed = await archivedIssue("Highest number so far");
    await runCleanupArchivedJob(at(GROWTH_RETENTION_DAYS * DAY + 2 * DAY));

    expect(await issueRepo.findIssueById(orgId, doomed.id)).toBeNull();
    await expect(
      issueRepo.nextIssueNumber(orgId, tenant.project.id),
    ).resolves.toBe(doomed.number + 1);
  });
});

