    await searchRepo.upsertSearchDocument(orgId, "comment", comment.id, "goodbye", null);

    const storageBefore = (await usageRepo.getUsage(orgId)).storageMbUsed;
    const issuesBefore = (await usageRepo.getUsage(orgId)).issuesUsed;

    await issueService.archiveIssue(tenant.actors.member, orgId, issue.id);
    await runCleanupArchivedJob(at(GROWTH_RETENTION_DAYS * DAY + DAY));

    expect(await issueRepo.findIssueById(orgId, issue.id)).toBeNull();
    expect(await commentRepo.listThread(orgId, issue.id)).toEqual([]);
    expect(await attachmentRepo.listAttachments(orgId, issue.id)).toEqual([]);

    const usage = await usageRepo.getUsage(orgId);
    expect(usage.storageMbUsed).toBe(storageBefore - 3);
    expect(usage.issuesUsed).toBe(issuesBefore);

    const indexedSubjects = getDb()
      .select({ subjectId: searchIndex.subjectId })
      .from(searchIndex)
      .all()
      .map((row) => row.subjectId);
    expect(indexedSubjects).not.toContain(issue.id);
    expect(indexedSubjects).not.toContain(comment.id);

    await expect(
      issueService.restoreIssue(tenant.actors.member, orgId, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("never hands a purged issue's number back out", async () => {
    const orgId = tenant.org.id;
    const doomed = await archivedIssue("Highest number so far");
    await runCleanupArchivedJob(at(GROWTH_RETENTION_DAYS * DAY + 2 * DAY));

    expect(await issueRepo.findIssueById(orgId, doomed.id)).toBeNull();
    await expect(
      issueRepo.nextIssueNumber(orgId, tenant.project.id),
    ).resolves.toBe(doomed.number + 1);
  });
});
